// ============================================
// Module Augmentation
// ============================================

import type {
  I18nProviderProps,
  UseLanguageSwitcherReturn,
  UseTranslationReturn,
} from "i18nexus";
import type {
  GetTranslationOptions,
  GetTranslationReturn,
} from "i18nexus/server";

declare module "i18nexus" {
  /**
   * Type-safe translation hook (Client Component)
   *
   * @template NS - The namespace to use
   * @param namespace - The namespace string
   * @returns Translation utilities with type-safe keys
   *
   * Note: Keys from the fallback namespace "common" are automatically included.
   *
   * @example
   * ```tsx
   * const { t } = useTranslation<"home">("home");
   * t("title");  // ✅ OK (from home namespace)
   * t("common-key");  // ✅ OK (from fallback namespace)
   * t("typo");   // ❌ Compile error!
   * ```
   */
  export function useTranslation<
    NS extends TranslationNamespace = TranslationNamespace,
  >(namespace: NS): UseTranslationReturn<TranslationKeys[NS] | CommonKeys>;

  /**
   * Language switcher hook (Client Component)
   *
   * @returns Language switching utilities
   *
   * @example
   * ```tsx
   * const { changeLanguage, availableLanguages } = useLanguageSwitcher();
   * changeLanguage("en");  // ✅ Change to English
   * ```
   */
  export function useLanguageSwitcher(): UseLanguageSwitcherReturn;

  /**
   * I18nProvider component (Client Component)
   *
   * Provides i18n context to child components. Supports both eager and lazy loading.
   *
   * @template TTranslations - The namespace translations structure
   * @param props - Props for the I18nProvider
   * @returns React.ReactElement
   *
   * @example
   * ```tsx
   * // Lazy loading (recommended)
   * <I18nProvider
   *   loadNamespace={async (ns, lang) => {
   *     const data = await import(\`./locales/\${ns}/\${lang}.json\`);
   *     return data.default;
   *   }}
   *   fallbackNamespace="common"
   * >
   *   <App />
   * </I18nProvider>
   *
   * // Eager loading
   * <I18nProvider translations={translations}>
   *   <App />
   * </I18nProvider>
   * ```
   */
  export function I18nProvider<
    TTranslations extends Record<
      string,
      Record<string, Record<string, string>>
    > = Record<string, Record<string, Record<string, string>>>,
  >(props: I18nProviderProps<TTranslations>): React.ReactElement;

  // Individual namespace key types (for use in constants and type definitions)
  export type AdminDashboardKeys = TranslationKeys["admin-dashboard"];
  export type CliKeys = TranslationKeys["cli"];
  export type CommonKeys = TranslationKeys["common"];
  export type ConstantKeys = TranslationKeys["constant"];
  export type DxLabKeys = TranslationKeys["dx-lab"];
  export type DocsI18nexusKeys = TranslationKeys["docs-i18nexus"];
  export type DocsI18nexusProviderKeys =
    TranslationKeys["docs-i18nexus-provider"];
  export type DocsI18nexusServerComponentsKeys =
    TranslationKeys["docs-i18nexus-server-components"];
  export type DocsI18nexusToolsKeys = TranslationKeys["docs-i18nexus-tools"];
  export type DocsI18nexusToolsDownloadKeys =
    TranslationKeys["docs-i18nexus-tools-download"];
  export type DocsI18nexusToolsDownloadForceKeys =
    TranslationKeys["docs-i18nexus-tools-download-force"];
  export type DocsI18nexusToolsExtractorKeys =
    TranslationKeys["docs-i18nexus-tools-extractor"];
  export type DocsI18nexusToolsGoogleSheetsKeys =
    TranslationKeys["docs-i18nexus-tools-google-sheets"];
  export type DocsI18nexusToolsUploadKeys =
    TranslationKeys["docs-i18nexus-tools-upload"];
  export type DocsI18nexusToolsWrapperKeys =
    TranslationKeys["docs-i18nexus-tools-wrapper"];
  export type DocsI18nexusUseLanguageSwitcherKeys =
    TranslationKeys["docs-i18nexus-use-language-switcher"];
  export type DocsI18nexusUseTranslationKeys =
    TranslationKeys["docs-i18nexus-use-translation"];
  export type GettingStartedKeys = TranslationKeys["getting-started"];
  export type HomeKeys = TranslationKeys["home"];
  export type ProviderKeys = TranslationKeys["provider"];
  export type ServerExampleKeys = TranslationKeys["server-example"];
  export type ShowcaseKeys = TranslationKeys["showcase"];
}

declare module "i18nexus/server" {
  /**
   * Type-safe translation function (Server Component)
   *
   * @template NS - The namespace to use
   * @param namespace - The namespace string (optional, auto-inferred)
   * @param options - Optional configuration
   * @returns Translation utilities with type-safe keys
   *
   * @example
   * ```tsx
   * const { t } = await getTranslation<"home">("home");
   * t("title");  // ✅ OK
   * t("typo");   // ❌ Compile error!
   * ```
   */
  export function getTranslation<
    NS extends TranslationNamespace = TranslationNamespace,
  >(
    namespace?: NS,
    options?: GetTranslationOptions,
  ): Promise<GetTranslationReturn<NS, TranslationKeys[NS] | CommonKeys>>;
}
